import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Subscription } from 'rxjs';
import { Trip } from '../../models/trip';
import { TripService } from '../../services/trip.service';
import { AuthService } from '../../services/auth.service';
import { TripCardComponent } from '../trip-card/trip-card.component';

@Component({
  selector: 'app-trip-list',
  standalone: true,
  imports: [CommonModule, RouterModule, TripCardComponent],
  templateUrl: './trip-list.component.html',
  styleUrls: ['./trip-list.component.css']
})
export class TripListComponent implements OnInit, OnDestroy {
  trips: Trip[] = [];
  loading = true;
  error: string | null = null;
  isAuthenticated = false;
  
  private authSubscription?: Subscription;

  constructor(
    private tripService: TripService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    // Subscribe to authentication state
    this.authSubscription = this.authService.isAuthenticated$.subscribe(
      isAuth => {
        this.isAuthenticated = isAuth;
      }
    );

    this.loadTrips();
  }

  ngOnDestroy(): void {
    if (this.authSubscription) {
      this.authSubscription.unsubscribe();
    }
  }

  loadTrips(): void {
    this.loading = true;
    this.error = null;

    this.tripService.getTrips().subscribe({
      next: (trips) => {
        this.trips = trips;
        this.loading = false;
      },
      error: (error) => {
        console.error('Error loading trips:', error);
        this.error = 'Failed to load trips. Please try again.';
        this.loading = false;
      }
    });
  }

  onTripDeleted(tripId: string): void {
    this.tripService.deleteTrip(tripId).subscribe({
      next: () => {
        // Remove the trip from the local array
        this.trips = this.trips.filter(trip => trip._id !== tripId);
      },
      error: (error) => {
        console.error('Error deleting trip:', error);
        this.error = 'Failed to delete trip. Please try again.';
      }
    });
  }

  trackByTripId(index: number, trip: Trip): string {
    return trip._id || index.toString();
  }

  getTripStats() {
    if (!this.trips.length) {
      return {
        total: 0,
        averageDuration: 0,
        priceRange: { min: 0, max: 0 }
      };
    }

    const prices = this.trips.map(trip => {
      const price = parseFloat(trip.perPerson.replace(/[^0-9.]/g, ''));
      return isNaN(price) ? 0 : price;
    });

    const durations = this.trips.map(trip => {
      const match = trip.length.match(/(\d+)\s*days?/i);
      return match ? parseInt(match[1], 10) : 0;
    });

    return {
      total: this.trips.length,
      averageDuration: Math.round(durations.reduce((a, b) => a + b, 0) / durations.length),
      priceRange: {
        min: Math.min(...prices),
        max: Math.max(...prices)
      }
    };
  }

  formatPrice(price: number): string {
    return `$${price.toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  }
}

