import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Trip } from '../../models/trip';

@Component({
  selector: 'app-trip-card',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './trip-card.component.html',
  styleUrls: ['./trip-card.component.css']
})
export class TripCardComponent {
  @Input() trip!: Trip;
  @Input() showAdminActions = false;
  @Output() deleteTrip = new EventEmitter<string>();

  showDeleteConfirm = false;
  deleting = false;

  onDelete(): void {
    this.showDeleteConfirm = true;
  }

  confirmDelete(): void {
    if (this.trip._id) {
      this.deleting = true;
      this.deleteTrip.emit(this.trip._id);
    }
  }

  cancelDelete(): void {
    this.showDeleteConfirm = false;
  }

  onImageError(event: Event): void {
    const target = event.target as HTMLImageElement;
    if (target) {
      target.src = 'https://via.placeholder.com/400x250?text=No+Image';
    }
  }

  formatPrice(price: string): string {
    if (!price) return '$0.00';
    
    // If price already has $ sign, return as is
    if (price.includes('$')) {
      return price;
    }
    
    // Otherwise, add $ sign and format
    const numericPrice = parseFloat(price.replace(/[^0-9.]/g, ''));
    if (isNaN(numericPrice)) return '$0.00';
    
    return `$${numericPrice.toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  }

  formatDate(dateString: string): string {
    if (!dateString) return 'TBD';
    
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      });
    } catch {
      return dateString;
    }
  }

  truncateDescription(description: string): string {
    if (!description) return '';
    
    const maxLength = 120;
    if (description.length <= maxLength) {
      return description;
    }
    
    return description.substring(0, maxLength).trim() + '...';
  }

  getDurationBadgeClass(duration: string): string {
    if (!duration) return 'bg-secondary';
    
    const days = this.extractDays(duration);
    if (days <= 3) return 'bg-info';
    if (days <= 5) return 'bg-warning';
    return 'bg-success';
  }

  getPriceBadgeClass(price: string): string {
    if (!price) return 'bg-secondary';
    
    const numericPrice = parseFloat(price.replace(/[^0-9.]/g, ''));
    if (isNaN(numericPrice)) return 'bg-secondary';
    
    if (numericPrice < 1000) return 'bg-success';
    if (numericPrice < 1500) return 'bg-warning';
    return 'bg-danger';
  }

  private extractDays(duration: string): number {
    const match = duration.match(/(\d+)\s*days?/i);
    return match ? parseInt(match[1], 10) : 0;
  }
}

